$targets = @(
  "$env:USERPROFILE\.local\share\opencode\auth.json",
  "$env:LOCALAPPDATA\opencode\auth.json",
  "$env:USERPROFILE\.claude\settings.json",
  "$env:USERPROFILE\.claude.json",
  "$env:USERPROFILE\.config\opencode\opencode.json"
)
foreach ($p in $targets) { if (Test-Path $p) { "EXISTS  : $p" } else { "missing : $p" } }
"--- auth.json top-level provider keys (values NOT printed) ---"
$auth = "$env:USERPROFILE\.local\share\opencode\auth.json"
if (Test-Path $auth) {
  try { ($null = Get-Content $auth -Raw | ConvertFrom-Json).PSObject.Properties | ForEach-Object { "  provider: $($_.Name)  (subkeys: $(($_.Value.PSObject.Properties.Name) -join ','))" } } catch { "  parse failed: $($_.Exception.Message)" }
}
"--- env vars (existence only) ---"
foreach ($n in @('ZAI_API_KEY','ZHIPU_API_KEY','GLM_API_KEY','ANTHROPIC_AUTH_TOKEN','ANTHROPIC_BASE_URL')) {
  $v = [Environment]::GetEnvironmentVariable($n)
  if ($v) { "  $n = <set, len=$($v.Length)>" } else { "  $n = <unset>" }
}
"--- claude settings: does it declare an anthropic token? (boolean only) ---"
$cs = "$env:USERPROFILE\.claude\settings.json"
if (Test-Path $cs) { try { $j = Get-Content $cs -Raw | ConvertFrom-Json; "  env.ANTHROPIC_AUTH_TOKEN present: $([bool]$j.env.ANTHROPIC_AUTH_TOKEN)"; "  env keys: $(($j.env.PSObject.Properties.Name) -join ',')" } catch { "  parse failed" } }

