def clean():
    """Clean build and dist directories.

    A config.json in dist/ may hold real credentials (the app writes one
    next to the executable when run). It is deleted rather than preserved,
    so that no credential can survive a rebuild or ship inside a
    distributed package.
    """
    stale_cfg = CONFIG_FILE
    if os.path.exists(stale_cfg):
        try:
            os.remove(stale_cfg)
        except Exception:
            pass

    if os.path.exists('build'):
        shutil.rmtree('build', ignore_errors=True)
    if os.path.exists('dist'):
        shutil.rmtree('dist', ignore_errors=True)

