[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
'===== 精确定位运行中窗口的真实矩形（Win32）====='
Add-Type @"
using System; using System.Text; using System.Collections.Generic; using System.Runtime.InteropServices;
public class W {
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc cb, IntPtr p);
  public delegate bool EnumProc(IntPtr h, IntPtr p);
  [DllImport("user32.dll")] public static extern int GetClassName(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern int GetWindowText(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
  public struct RECT { public int Left, Top, Right, Bottom; }
  public static List<string> Find() {
    var res = new List<string>();
    EnumWindows((h,p) => {
      var sb = new StringBuilder(256); GetClassName(h, sb, 256);
      var cn = sb.ToString();
      var tb = new StringBuilder(256); GetWindowText(h, tb, 256);
      var tn = tb.ToString();
      RECT r; GetWindowRect(h, out r);
      if (cn.StartsWith("Tk") || tn.Contains("TokenHub"))
        res.Add(String.Format("class={0}  title='{1}'  visible={2}  rect=({3},{4})-({5},{6})  size={7}x{8}",
          cn, tn, IsWindowVisible(h), r.Left, r.Top, r.Right, r.Bottom, r.Right-r.Left, r.Bottom-r.Top));
      return true;
    }, IntPtr.Zero);
    return res;
  }
}
"@
$found = [W]::Find()
if ($found) { $found | ForEach-Object { '  ' + $_ } } else { '  没找到 Tk 类窗口（进程可能没在跑）' }
''
'  期望：rect=(388,8)-(1148,133)  size=760x125'
'  屏幕：1536x960，所以 x 最大合法左缘 = 1536-760 = 776'

