  $yy = [int]($r1[3] * $iy / 5); $row = '  y=' + $yy.ToString().PadLeft(3) + ' : '
  for ($ix = 1; $ix -le 6; $ix++) {
    $xx = [int]($r1[2] * $ix / 7); $c = $bmp.GetPixel($xx, $yy)
    $row += ('{0,4},{1,4},{2,4}  ' -f $c.R, $c.G, $c.B)
  }
  $row
}
$bmp.Dispose()
'  -> ui_v2_1x.png / ui_v2_3x.png'

