Add-Type @"
using System; using System.Text; using System.Collections.Generic; using System.Runtime.InteropServices;
public class W7 {
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc cb, IntPtr p);
  public delegate bool EnumProc(IntPtr h, IntPtr p);
  [DllImport("user32.dll")] public static extern int GetClassName(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
  [DllImport("user32.dll")] public static extern IntPtr WindowFromPoint(POINT p);
  [DllImport("user32.dll")] public static extern int GetWindowRgn(IntPtr h, IntPtr hrgn);
  [DllImport("gdi32.dll")] public static extern IntPtr CreateRectRgn(int a,int b,int c,int d);
  [DllImport("gdi32.dll")] public static extern int GetRgnBox(IntPtr hrgn, out RECT r);
  [DllImport("user32.dll")] public static extern int GetWindowLong(IntPtr h, int i);
  public struct RECT { public int Left, Top, Right, Bottom; }
  public struct POINT { public int X, Y; }
  public static IntPtr H = IntPtr.Zero; public static int[] R = null;
  public static void Find() {
    EnumWindows((h,p) => {
      var sb = new StringBuilder(64); GetClassName(h, sb, 64);
      if (sb.ToString().StartsWith("Tk") && IsWindowVisible(h)) {
        RECT r; GetWindowRect(h, out r);
        if (r.Right-r.Left == 760 && H == IntPtr.Zero) { H = h; R = new int[]{r.Left,r.Top,r.Right-r.Left,r.Bottom-r.Top}; }
      }
      return true;
    }, IntPtr.Zero);
  }
  public static string ClassOf(IntPtr h) { var sb = new StringBuilder(64); GetClassName(h, sb, 64); return sb.ToString(); }
}
"@
[W7]::Find()
$r = [W7]::R
'窗口 hwnd={0}  rect=({1},{2}) {3}x{4}' -f [W7]::H, $r[0],$r[1],$r[2],$r[3]

'--- 窗口区域(Region)是否被裁空 ---'
$hrgn = [W7]::CreateRectRgn(0,0,1,1)
$res = [W7]::GetWindowRgn([W7]::H, $hrgn)
'  GetWindowRgn 返回 = ' + $res + '  (0=NULLREGION 1=SIMPLEREGION 2=COMPLEXREGION 3=ERROR)'
$box = New-Object W7+RECT
[void][W7]::GetRgnBox($hrgn, [ref]$box)
'  区域包围盒 = ({0},{1})-({2},{3})   即 {4}x{5}' -f $box.Left,$box.Top,$box.Right,$box.Bottom,($box.Right-$box.Left),($box.Bottom-$box.Top)

'--- 用 WindowFromPoint 问系统：窗口中心最上层是谁 ---'
$cx = $r[0] + [int]($r[2]/2); $cy = $r[1] + [int]($r[3]/2)
$pt = New-Object W7+POINT; $pt.X = $cx; $pt.Y = $cy
$top = [W7]::WindowFromPoint($pt)
'  点 ({0},{1}) 最上层 class = {2}' -f $cx, $cy, [W7]::ClassOf($top)
'  是否就是悬浮窗 = ' + ($top -eq [W7]::H)

'--- 扩展样式（0x80000=LAYERED, 0x20=TRANSPARENT）---'
$ex = [W7]::GetWindowLong([W7]::H, -20)
'  GWL_EXSTYLE = 0x{0:X}   LAYERED={1}  TRANSPARENT={2}' -f $ex, (($ex -band 0x80000) -ne 0), (($ex -band 0x20) -ne 0)

