input.command:
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$app = "C:\Users\29871\AppData\Local\Programs\Token Monitor"
$ud  = Join-Path $env:APPDATA "Token Monitor"

'===== 安装结果 ====='
Get-ChildItem $app -File | Sort-Object Length -Descending | Select-Object -First 4 |
  ForEach-Object { '  {0,-34} {1,9:N1} MB' -f $_.Name, ($_.Length/1MB) }
''
'  是否被设为开机自启（HKCU Run）：'
$run = Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run' -ErrorAction SilentlyContinue
$hit = $run.PSObject.Properties | Where-Object { $_.Name -match '(?i)token' }
if ($hit) { $hit | ForEach-Object { '    ' + $_.Name + ' = ' + $_.Value } } else { '    无' }

''
'===== 任务 2.1 首次启动（不录入任何凭证）====='
$exe = Get-ChildItem $app -Filter "*.exe" | Where-Object { $_.Name -notmatch '(?i)uninstall' } | Select-Object -First 1
'  可执行: ' + $exe.Name
Start-Process -FilePath $exe.FullName
'  已启动，等待 userData 生成 …'
$ok = $false
for ($i = 1; $i -le 40; $i++) {
  Start-Sleep -Seconds 1
  if (Test-Path $ud) { $ok = $true; '  第 ' + $i + ' 秒出现 userData: ' + $ud; break }
}
if (-not $ok) { '  ⚠ 40 秒内未出现 ' + $ud + '，列出 %APPDATA% 下最近改动目录：'; Get-ChildItem $env:APPDATA -Directory | Sort-Object LastWriteTime -Descending | Select-Object -First 6 | ForEach-Object { '    ' + $_.Name } }

''
'===== 任务 2.2 定位凭证文件 ====='
if (Test-Path $ud) {
  '  userData 内容：'
  Get-ChildItem $ud -Force | Sort-Object Name | ForEach-Object {
    '    {0,-28} {1,-8} {2,8} B' -f $_.Name, $(if ($_.PSIsContainer) { '<DIR>' } else { 'file' }), $_.Length
  }
  $cred = Join-Path $ud "credentials.json"
  '  credentials.json 是否存在: ' + (Test-Path $cred)
} else { '  userData 不存在，跳过' }

''
'===== 关闭应用（避免加固时文件被占用/被重写）====='
Get-Process | Where-Object { $_.Path -like "*Token Monitor*" } | ForEach-Object {
  '  结束 PID ' + $_.Id + '  (' + $_.ProcessName + ')'
  Stop-Process -Id $_.Id -Force -ErrorAction SilentlyContinue
}
Start-Sleep -Seconds 3

''
'===== 任务 2.3 记录加固前的原始 ACL ====='
'  --- userData 目录 ---'
icacls $ud 2>&1 | ForEach-Object { '    ' + $_ }
$cred = Join-Path $ud "credentials.json"
if (Test-Path $cred) { '  --- credentials.json ---'; icacls $cred 2>&1 | ForEach-Object { '    ' + $_ } }
else { '  credentials.json 尚不存在（符合预期：还没录入任何凭证）' }

