  ForEach-Object { '  {0,-24} {1,8} B  改于 {2}' -f $_.Name, $_.Length, $_.LastWriteTime }

''
function Show-Shape($obj, $prefix, $depth) {
  if ($depth -gt 4) { return }
  foreach ($pp in $obj.PSObject.Properties) {
    $path = if ($prefix) { "$prefix.$($pp.Name)" } else { $pp.Name }
    $v = $pp.Value
    if ($null -eq $v) { "  $path = null" }
    elseif ($v -is [string]) {
      if ($v.Length -eq 0) { "  $path = <空字符串>" }
      else { "  $path = <string 长度=$($v.Length) 前缀=$($v.Substring(0,[Math]::Min(4,$v.Length)))…>" }
    }
    elseif ($v -is [bool] -or $v -is [int] -or $v -is [long] -or $v -is [double]) { "  $path = $v" }
    elseif ($v -is [System.Management.Automation.PSCustomObject]) { "  $path = {"; Show-Shape $v $path ($depth+1); "  }" }
    elseif ($v -is [System.Array]) { "  $path = [array 共 $($v.Count) 项]"; $i=0; foreach ($e in $v) { if ($e -is [string]) { "    $path[$i] = <string 长度=$($e.Length)>" } else { "    $path[$i] = <$($e.GetType().Name)>" }; $i++ } }
    else { "  $path = <$($v.GetType().Name)>" }
  }
}

foreach ($f in @('settings.json','credentials.json')) {
  $fp = Join-Path $ud $f
  ''
  "===== 3. $f 结构 ====="
  if (Test-Path $fp) {
    try { Show-Shape (Get-Content $fp -Raw -Encoding UTF8 | ConvertFrom-Json) '' 0 }
    catch { '  ⚠ JSON 解析失败: ' + $_.Exception.Message }
  } else { '  不存在' }
}

''
'===== 4. 凭证文件 ACL ====='
$cf = Join-Path $ud 'credentials.json'
if (Test-Path $cf) { icacls $cf 2>&1 | ForEach-Object { '  ' + $_ } } else { '  credentials.json 不存在' }

''
'===== 5. 应用日志 ====='
foreach ($lg in @((Join-Path $ud 'logs\main.log'), (Join-Path $ud 'main.log'))) {
  if (Test-Path $lg) {
    '  --- ' + $lg + ' （末 40 行）---'
    Get-Content $lg -Tail 40 -Encoding UTF8 | ForEach-Object { '    ' + $_ }
  }
}
Get-ChildItem $ud -Recurse -Include '*.log' -ErrorAction SilentlyContinue |
  Where-Object { $_.Length -gt 0 } |
  Select-Object -First 5 | ForEach-Object { '  发现日志: ' + $_.FullName + '  (' + $_.Length + ' B)' }

