input.command:
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$ud = Join-Path $env:APPDATA "Token Monitor"
$glm = (Get-Content "$env:USERPROFILE\.local\share\opencode\auth.json" -Raw -Encoding UTF8 | ConvertFrom-Json).'zhipuai-coding-plan'.key
$cc  = (Get-Content (Join-Path $ud 'credentials.json') -Raw -Encoding UTF8 | ConvertFrom-Json).credentials.providers.commandcode.cookie

'===== A. GLM（open.bigmodel.cn，Authorization 不带 Bearer）====='
try {
  $r = Invoke-RestMethod -Uri 'https://open.bigmodel.cn/api/monitor/usage/quota/limit' `
       -Headers @{ 'Authorization' = $glm; 'Accept' = '*/*'; 'User-Agent' = 'Mozilla/5.0' } -TimeoutSec 30
  '  HTTP 200  code=' + $r.code + '  success=' + $r.success + '  level=' + $r.data.level
  $r.data.limits | ForEach-Object {
    $rem = ''
    if ($_.nextResetTime) {
      $dt = [DateTimeOffset]::FromUnixTimeMilliseconds([long]$_.nextResetTime).ToLocalTime()
      $sec = [math]::Round(([DateTimeOffset]::FromUnixTimeMilliseconds([long]$_.nextResetTime) - [DateTimeOffset]::Now).TotalSeconds)
      $rem = '  重置=' + $dt.ToString('MM-dd HH:mm') + ' （剩余 ' + $sec + ' 秒 = ' + [math]::Round($sec/3600,2) + ' 小时）'
    } else { $rem = '  重置=null' }
    '    type={0,-13} unit={1,-3} number={2,-3} usage={3,-7} current={4,-7} pct={5}%{6}' -f $_.type, $_.unit, $_.number, $_.usage, $_.currentValue, $_.percentage, $rem
  }
} catch { '  ❌ 失败: HTTP ' + $_.Exception.Response.StatusCode.value__ + '  ' + $_.Exception.Message }

''
'===== B. CommandCode（billing/credits）====='
try {
  $r2 = Invoke-RestMethod -Uri 'https://api.commandcode.ai/internal/billing/credits' `
        -Headers @{ 'Cookie' = "__Secure-commandcode_prod_.session_token=$cc"; 'Accept' = '*/*'; 'User-Agent' = 'Mozilla/5.0' } -TimeoutSec 30
  $w = $r2.windowLimits
  '  HTTP 200'
  '  fiveHour: used={0}  cap={1}  => {2:N2}%   resetAt={3}' -f $w.fiveHour.used, $w.fiveHour.cap, ($w.fiveHour.used/$w.fiveHour.cap*100), ([DateTimeOffset]::FromUnixTimeMilliseconds([long]$w.fiveHour.resetAt).ToLocalTime().ToString('MM-dd HH:mm'))
  '  weekly  : used={0}  cap={1}  => {2:N2}%   resetAt={3}' -f $w.weekly.used, $w.weekly.cap, ($w.weekly.used/$w.weekly.cap*100), ([DateTimeOffset]::FromUnixTimeMilliseconds([long]$w.weekly.resetAt).ToLocalTime().ToString('MM-dd HH:mm'))
  '  credits.monthlyCredits(剩余) = ' + $r2.credits.monthlyCredits
  '  credits.monthlyCreditsGranted = ' + $(if ($null -eq $r2.credits.monthlyCreditsGranted) { 'null' } else { $r2.credits.monthlyCreditsGranted })
  '  credits.opensourceMonthlyCredits = ' + $r2.credits.opensourceMonthlyCredits
  '  limited = ' + $w.limited
} catch { '  ❌ 失败: HTTP ' + $_.Exception.Response.StatusCode.value__ + '  ' + $_.Exception.Message }

''
'===== C. Token Monitor 重启后写入过哪些文件（近 8 分钟）====='
$cut = (Get-Date).AddMinutes(-8)
Get-ChildItem $ud -File -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -gt $cut } |
  Sort-Object LastWriteTime -Descending | ForEach-Object { '  {0,-34} {1,9} B  {2}' -f $_.Name, $_.Length, $_.LastWriteTime.ToString('HH:mm:ss') }

''
'===== D. 有没有可读的 limits 缓存可用来判断它是否取数成功 ====='
Get-ChildItem $ud -Recurse -File -ErrorAction SilentlyContinue |
  Where-Object { $_.Name -match '(?i)limit|quota|provider' -and $_.Length -gt 0 } |
  Select-Object -First 10 | ForEach-Object { '  ' + $_.FullName.Replace($ud,'') + '  (' + $_.Length + ' B)' }

