input.content:
# -*- coding: utf-8 -*-
"""诊断：(A) TokenHub 的 GLM 显示是否反转 (B) 归类函数如何处理 null nextResetTime
(C) Token Monitor 的 CommandCode 实现到底要什么"""
import io
import json
import os
import re
import sys

sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8", errors="replace")

PROJ = r"D:\桌面\私人图书馆\7-工具箱\1-project\TokenHub"
TMP = r"C:\Users\29871\AppData\Local\Temp\opencode"
UD = os.path.join(os.environ["APPDATA"], "Token Monitor")


def hr(t):
    print("\n" + "=" * 4 + " " + t + " " + "=" * 4)


# ---------- A ----------
hr("A. TokenHub log: glm readings (check inversion)")
logp = os.path.join(PROJ, "tokenhub.log")
if os.path.exists(logp):
    with open(logp, encoding="utf-8", errors="replace") as fh:
        lines = fh.readlines()
    hits = [l.strip() for l in lines if ("glm_rolling" in l or "glm_weekly" in l)]
    for l in hits[-8:]:
        print("  " + l)
    print("\n  EXPECT rolling=0%~small, weekly=11%")
    print("  INVERTED if you see rolling: 11% together with weekly: 0%")
else:
    print("  log not found")

# ---------- B ----------
hr("B. src/api.py : _glm_classify_windows source")
apip = os.path.join(PROJ, "src", "api.py")
with open(apip, encoding="utf-8", errors="replace") as fh:
    src = fh.readlines()
start = None
for i, l in enumerate(src):
    if "def _glm_classify_windows" in l:
        start = i
        break
if start is not None:
    print(f"  def at line {start+1}")
    for j in range(start, min(start + 46, len(src))):
        print(f"  {j+1:4d}| {src[j].rstrip()}")
    # 找出用到该辅助函数的位置，确认 nextResetTime 缺失时的取值
print("\n  --- grep for nextResetTime handling in api.py ---")
for i, l in enumerate(src):
    if "nextResetTime" in l or "reset_at_ms" in l or "reset_sec" in l:
        print(f"  {i+1:4d}| {l.rstrip()}")

# ---------- C ----------
hr("C. token-monitor CommandCode provider")
ccp = os.path.join(TMP, "tm-full", "src", "shared", "providers", "commandcode", "limits.js")
if os.path.exists(ccp):
    with open(ccp, encoding="utf-8", errors="replace") as fh:
        cl = fh.readlines()
    print(f"  file lines = {len(cl)}")
    pat = re.compile(r"session_token|__Secure|https?://|userId|accountId|account_id|Cookie|cookie|commandcode\.ai", re.I)
    print("\n  --- matching lines (first 45) ---")
    n = 0
    for i, l in enumerate(cl):
        if pat.search(l):
            print(f"  {i+1:4d}| {l.rstrip()[:150]}")
            n += 1
            if n >= 45:
                break
    print("\n  --- function commandcodeCookie ---")
    for i, l in enumerate(cl):
        if re.match(r"\s*function commandcodeCookie", l):
            for j in range(i, min(i + 26, len(cl))):
                print(f"  {j+1:4d}| {cl[j].rstrip()}")
            break
else:
    print("  not found:", ccp)

# ---------- D ----------
hr("D. token-monitor commandcode state files")
if os.path.isdir(UD):
    for f in sorted(os.listdir(UD)):
        p = os.path.join(UD, f)
        if os.path.isfile(p) and re.search(r"command|cc", f, re.I):
            print(f"  {f}  {os.path.getsize(p)} B")
    for f in sorted(os.listdir(UD)):
        p = os.path.join(UD, f)
        if os.path.isfile(p) and f.endswith(".json") and os.path.getsize(p) < 60000:
            try:
                t = open(p, encoding="utf-8", errors="replace").read()
                if "commandcode" in t.lower():
                    print(f"  contains 'commandcode': {f} ({os.path.getsize(p)} B)")
            except Exception:
                pass
    sp = os.path.join(UD, "settings.json")
    if os.path.exists(sp):
        s = json.load(open(sp, encoding="utf-8"))
        print("\n  settings keys of interest:")
        for k in ("limitProviders", "limitProviderOrder", "limitsEnabled",
                  "limitsRefreshMode", "limitsRefreshMs", "collectionMode"):
            print(f"    {k} = {s.get(k)}")
        for k, v in s.items():
            if "commandcode" in k.lower():
                print(f"    {k} = {v}")

# ---------- E ----------
hr("E. token-monitor account id derivation (how it keys state)")
for cand in ("src/shared/providers/commandcode/limits.js", "src/shared/limits/collector.js"):
    p = os.path.join(TMP, "tm-full", *cand.split("/"))
    if not os.path.exists(p):
        continue
    t = open(p, encoding="utf-8", errors="replace").read()
    for m in re.finditer(r"sha256:[^`\"')]{0,80}|createHash\([^)]{0,60}\)|accountId[^\n]{0,90}", t):
        print(f"  [{cand}] {m.group(0)[:120]}")

