Write-Output ("  config.json exists: " + (Test-Path "src\config.json"))
Write-Output ("  src/api.py exists : " + (Test-Path "src\api.py"))

Write-Output ""
Write-Output "===== 5.4 settled memory (both tools, this sample) ====="
$tm = Get-Process | Where-Object { $_.ProcessName -like '*Token Monitor*' }
Write-Output ("  Token Monitor : " + @($tm).Count + " procs, {0:N1} MB" -f (($tm | Measure-Object WorkingSet64 -Sum).Sum/1MB))
if ($th) { Write-Output ("  TokenHub      : 1 proc,  {0:N1} MB" -f ((Get-Process -Id $th.ProcessId).WorkingSet64/1MB)) }

Write-Output ""
Write-Output "===== 6.3 regression checks on TokenHub ====="
Write-Output "  (a) GLM key must NOT be on disk in TokenHub config/log:"
$cfgTxt = Get-Content "src\config.json" -Raw -Encoding UTF8
$glmKey = (Get-Content "$env:USERPROFILE\.local\share\opencode\auth.json" -Raw -Encoding UTF8 | ConvertFrom-Json).'zhipuai-coding-plan'.key
Write-Output ("      config.json contains the GLM key value: " + $cfgTxt.Contains($glmKey))
$logTxt = Get-Content "tokenhub.log" -Raw -Encoding UTF8 -ErrorAction SilentlyContinue
Write-Output ("      tokenhub.log contains the GLM key value: " + $logTxt.Contains($glmKey))

Write-Output ""
Write-Output "  (b) config.json ACL (must be user-only, not BUILTIN\Users):"
icacls "src\config.json" 2>&1 | ForEach-Object { Write-Output ("      " + $_) }

Write-Output ""
Write-Output "  (c) dist/ build artifacts must not contain credentials:"
if (Test-Path "dist") {
  $hit = Get-ChildItem "dist" -Recurse -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -eq 'config.json' }
  Write-Output ("      config.json inside dist: " + @($hit).Count)
} else { Write-Output "      dist/ absent (not built)" }

Write-Output ""
Write-Output "  (d) git cleanliness:"
git status --short | ForEach-Object { Write-Output ("      " + $_) }
git log --oneline -1 | ForEach-Object { Write-Output ("      HEAD " + $_) }

