input.command:
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$ud = Join-Path $env:APPDATA "Token Monitor"

Write-Output "===== 5.3 concurrent polling: any rate-limit / failures in TokenHub log? ====="
$lines = Get-Content "tokenhub.log" -Encoding UTF8
Write-Output ("  total log lines: " + $lines.Count)
$since = $lines | Where-Object { $_ -match '^2026-09-15 14:4|^2026-09-15 14:5|^2026-09-15 15:' }
Write-Output ("  lines since 14:40 (token-monitor started): " + @($since).Count)
foreach ($pat in @('429','rate limit','Too Many','ERROR','Traceback','失败','error')) {
  $hits = $since | Select-String -Pattern $pat -SimpleMatch
  Write-Output ("  [" + $pat + "] hits since 14:40: " + @($hits).Count)
}
Write-Output ""
Write-Output "  --- last 6 WARNING/ERROR lines of the whole log ---"
$lines | Select-String -Pattern 'WARNING|ERROR' | Select-Object -Last 6 | ForEach-Object { Write-Output ("    " + $_.Line.Trim()) }

Write-Output ""
Write-Output "===== 5.5 evidence: token-monitor refresh activity ====="
Get-ChildItem $ud -File | Where-Object { $_.LastWriteTime -gt (Get-Date).AddMinutes(-20) } |
  Sort-Object LastWriteTime -Descending | ForEach-Object { Write-Output ("  {0,-34} {1}  ({2} B)" -f $_.Name, $_.LastWriteTime.ToString("HH:mm:ss"), $_.Length) }

Write-Output ""
Write-Output "===== TokenHub latest readings (post-reset, both windows) ====="
$lines | Select-String -Pattern 'glm_rolling|glm_weekly|cc_rolling|cc_weekly' | Select-Object -Last 4 | ForEach-Object { Write-Output ("  " + $_.Line.Trim()) }

Write-Output ""
Write-Output "===== temp clones still present (task 7.5) ====="
foreach ($d in @("tm","tm-full")) {
  $p = "C:\Users\29871\AppData\Local\Temp\opencode\$d"
  if (Test-Path $p) {
    $sz = (Get-ChildItem $p -Recurse -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
    Write-Output ("  {0,-9} {1,8:N1} MB" -f $d, ($sz/1MB))
  } else { Write-Output ("  " + $d + "  absent") }
}

