input.command:
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$tmp = "C:\Users\29871\AppData\Local\Temp\opencode"
$ud  = Join-Path $env:APPDATA "Token Monitor"

Write-Output "===== 7.5 delete temp clones of the third-party repo ====="
foreach ($d in @("tm","tm-full")) {
  $p = Join-Path $tmp $d
  if (Test-Path $p) {
    $sz = (Get-ChildItem $p -Recurse -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
    Remove-Item $p -Recurse -Force -ErrorAction SilentlyContinue
    Write-Output ("  deleted {0}  ({1:N1} MB)" -f $d, ($sz/1MB))
  } else { Write-Output ("  " + $d + " already absent") }
}

Write-Output ""
Write-Output "===== delete my own credential copies and helper scripts ====="
$mine = @(
  "tm_cc_grab.py","tm-cc-grab.log","tm-cc-token.json",
  "fix_tm_credentials.py","fix_tm_cc_cookie_format.py","diag_cc.py"
)
foreach ($f in $mine) {
  $p = Join-Path $tmp $f
  if (Test-Path $p) { Remove-Item $p -Force; Write-Output ("  deleted " + $f) }
}
foreach ($f in (Get-ChildItem $ud -File -Filter 'credentials.json.bak*' -ErrorAction SilentlyContinue)) {
  Remove-Item $f.FullName -Force; Write-Output ("  deleted backup " + $f.Name + "  (held a stale credential value)")
}

Write-Output ""
Write-Output "===== verify no plaintext token copy remains in the temp dir ====="
$ccFull = (Get-Content (Join-Path $ud 'credentials.json') -Raw -Encoding UTF8 | ConvertFrom-Json).credentials.providers.commandcode.cookie
$tok = $ccFull.Substring($ccFull.IndexOf('=') + 1)
$leftover = @()
Get-ChildItem $tmp -File -ErrorAction SilentlyContinue | ForEach-Object {
  $t = Get-Content $_.FullName -Raw -ErrorAction SilentlyContinue
  if ($t -and $t.Contains($tok)) { $leftover += $_.Name }
}
if ($leftover.Count -eq 0) { Write-Output "  clean: no file in temp root contains the token" } else { Write-Output ("  STILL PRESENT in: " + ($leftover -join ', ')) }
Write-Output ("  credentials.json.bak* remaining: " + @(Get-ChildItem $ud -File -Filter 'credentials.json.bak*' -ErrorAction SilentlyContinue).Count)

Write-Output ""
Write-Output "===== commit ====="
git add -A
git status --short | ForEach-Object { Write-Output ("  " + $_) }
git commit -m "docs(adopt-token-monitor): 完成对账并记录 TokenHub 降级为对账基准" -m "- 新增对账记录 openspec/changes/adopt-token-monitor/reconciliation.md
- 稳定锚点全部相符：GLM 2000/10000、CommandCode 14/35；实测与直连接口一致
- 确认并解释 CommandCode 月度口径偏差（硬编码 70 vs 实测 74.107，约 -1.4pp）
- 更正一处未实测的调研结论：token-monitor 无贴边收纳能力
- README 新增角色变更、可信数字清单、回退步骤、能力差异对照
- CHANGELOG 新增 0.1.3（本次切换未修改任何 src/ 代码）
- 补写两个基线 spec 的 Purpose，不再保留 TBD" | Select-Object -Last 3
Write-Output ""
git log --oneline -3 | ForEach-Object { Write-Output ("  " + $_) }
$s = git status --short
if ($s) { Write-Output "  dirty:"; $s | ForEach-Object { Write-Output ("    " + $_) } } else { Write-Output "  working tree clean" }

Write-Output ""
Write-Output "===== validate ====="
openspec validate --all --strict 2>&1 | ForEach-Object { Write-Output ("  " + $_) }
openspec list 2>&1 | ForEach-Object { Write-Output ("  " + $_) }

