[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
Write-Output "===== task completion ====="
$t = Get-Content "openspec\changes\adopt-token-monitor\tasks.md" -Encoding UTF8
$done = @($t | Select-String -Pattern '^- \[x\]').Count
$todo = @($t | Select-String -Pattern '^- \[ \]').Count
Write-Output ("  checked   = " + $done)
Write-Output ("  unchecked = " + $todo)
if ($todo -gt 0) { $t | Select-String -Pattern '^- \[ \]' | ForEach-Object { Write-Output ("    " + $_.Line) } }

Write-Output ""
Write-Output "===== openspec status ====="
openspec status --change adopt-token-monitor 2>&1 | ForEach-Object { Write-Output ("  " + $_) }

Write-Output ""
Write-Output "===== both tools running ====="
$tm = Get-Process | Where-Object { $_.ProcessName -like '*Token Monitor*' }
Write-Output ("  token-monitor : " + @($tm).Count + " procs, {0:N1} MB" -f (($tm | Measure-Object WorkingSet64 -Sum).Sum/1MB))
$th = Get-CimInstance Win32_Process -Filter "Name like 'python%'" | Where-Object { $_.CommandLine -like '*main.py*' }
if ($th) { $pr = Get-Process -Id $th.ProcessId; Write-Output ("  TokenHub      : 1 proc,  {0:N1} MB  (PID {1})" -f ($pr.WorkingSet64/1MB), $pr.Id) }
else { Write-Output "  TokenHub      : NOT RUNNING" }

Write-Output ""
Write-Output "===== final live readings, both sides ====="
$glm = (Get-Content "$env:USERPROFILE\.local\share\opencode\auth.json" -Raw -Encoding UTF8 | ConvertFrom-Json).'zhipuai-coding-plan'.key
$r = Invoke-RestMethod -Uri 'https://open.bigmodel.cn/api/monitor/usage/quota/limit' -Headers @{ 'Authorization' = $glm; 'Accept'='*/*' } -TimeoutSec 30
