$wk = $r.data.limits | Where-Object { $_.usage -eq 10000 }
Write-Output ("  GLM    direct: 5h " + $w5.percentage + "%  / weekly " + $wk.percentage + "%")
$ud = Join-Path $env:APPDATA "Token Monitor"
$ccF = (Get-Content (Join-Path $ud 'credentials.json') -Raw -Encoding UTF8 | ConvertFrom-Json).credentials.providers.commandcode.cookie
$r2 = Invoke-RestMethod -Uri 'https://api.commandcode.ai/internal/billing/credits' -Headers @{ 'Cookie' = $ccF; 'Accept'='*/*' } -TimeoutSec 30
Write-Output ("  CC     direct: 5h " + [math]::Round($r2.windowLimits.fiveHour.used/$r2.windowLimits.fiveHour.cap*100,2) + "%  / weekly " + [math]::Round($r2.windowLimits.weekly.used/$r2.windowLimits.weekly.cap*100,2) + "%")
Get-Content "tokenhub.log" -Tail 120 -Encoding UTF8 | Select-String -Pattern 'glm_rolling|glm_weekly|cc_rolling|cc_weekly' | Select-Object -Last 4 | ForEach-Object { Write-Output ("  TokenHub log: " + $_.Line.Trim().Replace('2026-09-15 ','')) }

