  $hit = @()
  foreach ($k in @('asarIntegrity','algorithm','sha256')) { if ($txt -match $k) { $hit += $k } }
  Write-Output ("  exe contains markers: " + $(if ($hit.Count) { $hit -join ', ' } else { '(none found)' }))
  Write-Output "  NOTE: presence of the word is not proof; real check needs the build config."
}

