input.content:
# -*- coding: utf-8 -*-
"""直接解析 app.asar（不依赖 asar/npm 包）。

目的：
  1) 判断 Electron 的 asar integrity 是否真的启用（决定"改本地安装"这条路是否可行）
  2) 取出 package.json 的 name/productName/version/scripts
  3) 取出 src/electron/windowBehavior.js（拟新增贴边收纳时最可能要改的文件）

asar 容器格式（经验实现，两种 data_start 解释各试一次，用 package.json 是否解析成功来判定）：
  | u32 const | u32 headerSize | u32 headerJsonLen | headerJson | padding | 数据区 |
"""
import hashlib
import io
import json
import os
import sys

sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8", errors="replace")

ASAR = r"C:\Users\29871\AppData\Local\Programs\Token Monitor\resources\app.asar"
EXE = r"C:\Users\29871\AppData\Local\Programs\Token Monitor\Token Monitor.exe"

raw = open(ASAR, "rb").read()
print(f"asar size = {len(raw):,} B")

u32 = lambda o: int.from_bytes(raw[o:o + 4], "little")
c0, header_size, json_len = u32(0), u32(4), u32(8)

header = None
for cand in (raw[12:12 + json_len], raw[8:8 + header_size], raw[12:12 + header_size]):
    try:
        d = json.loads(cand.decode("utf-8", errors="replace"))
        if isinstance(d, dict) and "files" in d:
            header = d
            break
    except Exception:
        pass
if header is None:
    print("FATAL 无法解析 asar header")
    raise SystemExit(1)

print("\n===== 1. integrity 检查（决定性）=====")
print("  header 顶层键:", sorted(header.keys()))
if "integrity" in header:
    print("  *** header 内存在 integrity 字段 ***")
    print("  " + json.dumps(header["integrity"], ensure_ascii=False, indent=2)[:800])
else:
    print("  header 内无 integrity 字段")

# 双保险：把 header 里的 hash 拿去 exe 里找
def find_in_exe(h):
    if not h:
        return False
    try:
        with open(EXE, "rb") as fh:
            while True:
                chunk = fh.read(8 << 20)
                if not chunk:
                    return False
                if h.encode() in chunk:
                    return True
    except Exception as e:
        print("   exe 扫描失败:", e)
        return False

ig = header.get("integrity") or {}
h_val = ig.get("hash")
if h_val:
    print(f"  integrity.hash = {h_val[:16]}…（长度 {len(h_val)}）")
    print(f"  该 hash 是否出现在 exe 中: {find_in_exe(h_val)}")
else:
    print("  无 integrity.hash 可校验；exe 中出现的 'asarIntegrity'/'sha256' 字样来自 Electron 自身字符串表")

print("\n===== 2. data 区起点与文件读取 =====")
def resolve(path_parts):
    node = header
    for p in path_parts:
        node = (node.get("files") or {}).get(p)
        if node is None:
            return None
    return node

def read_file(path_parts):
    node = resolve(path_parts)
    if not node or "offset" not in node:
        return None
    off, size = int(node["offset"]), int(node["size"])
    for base in (8 + header_size, 12 + json_len, 8 + json_len):
        blob = raw[base + off: base + off + size]
        return blob
    return None

pkg = read_file(["package.json"])
if pkg:
    try:
        j = json.loads(pkg.decode("utf-8"))
        print("  package.json 读取成功")
        for k in ("name", "productName", "version", "main", "author"):
            print(f"    {k} = {j.get(k)}")
        print("    scripts =", json.dumps(j.get("scripts", {}), ensure_ascii=False))
        deps = j.get("devDependencies", {})
        print("    key devDeps =", {k: v for k, v in deps.items() if k in
              ("electron", "electron-builder", "@electron/asar", "electron-builder-squirrel-windows")})
    except Exception as e:
        print("  package.json 解析失败:", e)
else:
    print("  package.json 未找到")

print("\n===== 3. src/electron 下的文件 =====")
node = resolve(["src", "electron"])
if node:
    for name, meta in sorted((node.get("files") or {}).items()):
        kind = "DIR " if "files" in meta else f"{meta.get('size', 0):>8} B"
        print(f"  {kind}  {name}")
else:
    print("  src/electron 未找到")

print("\n===== 4. src/electron/windowBehavior.js 全文 =====")
wb = read_file(["src", "electron", "windowBehavior.js"])
if wb:
    txt = wb.decode("utf-8", errors="replace")
    print(f"  ({len(txt)} chars)")
    for i, line in enumerate(txt.splitlines(), 1):
        print(f"  {i:4d}| {line}")
else:
    print("  未找到 windowBehavior.js")

