Add-Type @"
using System;
using System.Text;
using System.Runtime.InteropServices;
public class W {
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc cb, IntPtr l);
  public delegate bool EnumWindowsProc(IntPtr h, IntPtr l);
  [DllImport("user32.dll")] public static extern int GetWindowTextW(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern int GetClassNameW(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
  public struct RECT { public int l, t, r, b; }
}
"@ -ErrorAction SilentlyContinue
$found = New-Object System.Collections.ArrayList
$cb = [W+EnumWindowsProc]{
  param($h, $l)
  $r = New-Object W+RECT
  [void][W]::GetWindowRect($h, [ref]$r)
  $w = $r.r - $r.l; $ht = $r.b - $r.t
  $pid2 = 0
  [void][W]::GetWindowThreadProcessId($h, [ref]$pid2)
  if ($pids -contains [int]$pid2) {
    $sb = New-Object System.Text.StringBuilder 256
    [void][W]::GetWindowTextW($h, $sb, 256)
    $cn = New-Object System.Text.StringBuilder 256
    [void][W]::GetClassNameW($h, $cn, 256)
    [void]$found.Add([pscustomobject]@{ hwnd=$h; w=$w; h=$ht; vis=[W]::IsWindowVisible($h); cls=$cn.ToString(); title=$sb.ToString() })
  }
  return $true
}
[void][W]::EnumWindows($cb, [IntPtr]::Zero)
$found | Sort-Object -Property @{Expression={$_.vis};Descending=$true}, @{Expression={$_.w*$_.h};Descending=$true} |
