$ErrorActionPreference = 'Continue'
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$log = "C:\Users\29871\AppData\Local\Temp\opencode\edge-debug.log"
$lines = Get-Content $log -Encoding UTF8
Write-Output ("总行数 " + $lines.Count)
Write-Output ""
Write-Output "===== 所有非重复事件行（HIDDEN/RECONCILE 的重复行折叠），带行号 ====="
$prev = ''
for ($i = 0; $i -lt $lines.Count; $i++) {
  $l = $lines[$i]
  $key = ($l -replace '^\S+ ', '') -replace '(cursor|exp|hidden|side|desired)=[^ ]*', '$1=?'
  if ($key -ne $prev) {
    Write-Output ("  " + ($i + 1).ToString().PadLeft(4) + "| " + $l)
    $prev = $key
  }
}
Write-Output ""
Write-Output "===== 关键行：EXPAND enter / hit=true 及其后 12 行 ====="
for ($i = 0; $i -lt $lines.Count; $i++) {
  if ($lines[$i] -match 'EXPAND enter|hit=true') {
    Write-Output ("  --- 第 " + ($i + 1) + " 行起 ---")
    for ($j = $i; $j -lt [Math]::Min($i + 13, $lines.Count); $j++) { Write-Output ("    " + $lines[$j]) }
    Write-Output ""
  }
}
Write-Output "===== 护栏/崩溃日志 ====="
$e = Join-Path $env:TEMP "token-monitor-edge-error.log"
if (Test-Path $e) { Get-Content $e -Encoding UTF8 | ForEach-Object { Write-Output ("  " + $_) } } else { Write-Output "  不存在（无护栏拒绝、无未捕获异常）" }

