Write-Output ("  windowBounds   = " + ($s.windowBounds | ConvertTo-Json -Compress))
Write-Output ("  edgeAutoHideBounds = " + $(if ($s.edgeAutoHideBounds) { ($s.edgeAutoHideBounds | ConvertTo-Json -Compress) } else { "null" }))

Write-Output ""
