  Write-Output "  存在："
  Get-Content $err -Encoding UTF8 | Select-Object -First 12 | ForEach-Object { Write-Output ("    " + $_) }
} else { Write-Output "  不存在（无未捕获异常、无护栏拒绝）" }

Write-Output ""
Write-Output "===== 是否有错误框 ====="
Add-Type @"
using System;using System.Text;using System.Runtime.InteropServices;
public class WW {
 [DllImport("user32.dll")] public static extern bool EnumWindows(P cb, IntPtr l);
 public delegate bool P(IntPtr h, IntPtr l);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)] public static extern int GetWindowTextW(IntPtr h, StringBuilder s, int n);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)] public static extern int GetClassNameW(IntPtr h, StringBuilder s, int n);
 [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
 [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out R r);
 [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
 public struct R { public int l,t,r,b; }
}
"@ -ErrorAction SilentlyContinue
$pids = @($p | ForEach-Object { $_.Id })
$found = New-Object System.Collections.ArrayList
$cb = [WW+P]{
  param($h,$l)
  $r = New-Object WW+R; [void][WW]::GetWindowRect($h,[ref]$r)
  $pid2 = 0; [void][WW]::GetWindowThreadProcessId($h,[ref]$pid2)
  if ($pids -contains [int]$pid2 -and [WW]::IsWindowVisible($h)) {
    $sb = New-Object System.Text.StringBuilder 256; [void][WW]::GetWindowTextW($h,$sb,256)
    $cn = New-Object System.Text.StringBuilder 128; [void][WW]::GetClassNameW($h,$cn,128)
    $w = $r.r-$r.l; $ht = $r.b-$r.t
    if ($w -gt 40 -and $ht -gt 40) { [void]$found.Add(("{0}x{1} at ({2},{3}) cls={4} title='{5}'" -f $w,$ht,$r.l,$r.t,$cn.ToString(),$sb.ToString())) }
  }
  return $true
}
[void][WW]::EnumWindows($cb,[IntPtr]::Zero)
if ($found.Count -eq 0) { Write-Output "  无可见主窗口" } else { $found | ForEach-Object { Write-Output ("  " + $_) } }

