$res = "C:\Users\29871\AppData\Local\Programs\Token Monitor\resources"
$ud  = Join-Path $env:APPDATA "Token Monitor"
$err = Join-Path $env:TEMP "token-monitor-edge-error.log"

Write-Output "===== 应用当前状态 ====="
$p = Get-Process | Where-Object { $_.ProcessName -like '*Token Monitor*' }
Write-Output ("  进程 " + @($p).Count + " 个, 合计 {0:N1} MB" -f (($p | Measure-Object WorkingSet64 -Sum).Sum/1MB))
Write-Output ("  app.asar {0,12:N0} B" -f (Get-Item (Join-Path $res 'app.asar')).Length)
