Add-Type @"
using System;using System.Text;using System.Runtime.InteropServices;
public class WZ {
 [DllImport("user32.dll")] public static extern bool EnumWindows(P cb, IntPtr l);
 public delegate bool P(IntPtr h, IntPtr l);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)] public static extern int GetWindowTextW(IntPtr h, StringBuilder s, int n);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)] public static extern int GetClassNameW(IntPtr h, StringBuilder s, int n);
 [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
 [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out R r);
 [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
 [DllImport("user32.dll")] public static extern bool SetCursorPos(int x, int y);
 public struct R { public int l,t,r,b; }
}
"@ -ErrorAction SilentlyContinue

function Get-MainWindow {
  $pids = @((Get-Process | Where-Object { $_.ProcessName -like '*Token Monitor*' }) | ForEach-Object { $_.Id })
  $best = $null
  $cb = [WZ+P]{
    param($h,$l)
    $r = New-Object WZ+R; [void][WZ]::GetWindowRect($h,[ref]$r)
    $pid2 = 0; [void][WZ]::GetWindowThreadProcessId($h,[ref]$pid2)
    if ($pids -contains [int]$pid2 -and [WZ]::IsWindowVisible($h)) {
      $cn = New-Object System.Text.StringBuilder 128; [void][WZ]::GetClassNameW($h,$cn,128)
      $w = $r.r-$r.l; $ht = $r.b-$r.t
      if ($w -gt 40 -and $ht -gt 40 -and $cn.ToString() -ne '#32770') {
        $script:best = [pscustomobject]@{ hwnd=$h; x=$r.l; y=$r.t; w=$w; h=$ht }
      }
    }
    return $true
  }
  [void][WZ]::EnumWindows($cb,[IntPtr]::Zero)
  return $script:best
}
function Get-Top($hwnd) { $r = New-Object WZ+R; [void][WZ]::GetWindowRect($hwnd,[ref]$r); return $r.t }
function Get-ErrDialogs {
  $pids = @((Get-Process | Where-Object { $_.ProcessName -like '*Token Monitor*' }) | ForEach-Object { $_.Id })
  $n = 0
  $cb = [WZ+P]{
    param($h,$l)
    if ([WZ]::IsWindowVisible($h)) {
      $pid2 = 0; [void][WZ]::GetWindowThreadProcessId($h,[ref]$pid2)
      if ($pids -contains [int]$pid2) {
        $cn = New-Object System.Text.StringBuilder 128; [void][WZ]::GetClassNameW($h,$cn,128)
        if ($cn.ToString() -eq '#32770') {
          $tn = New-Object System.Text.StringBuilder 256; [void][WZ]::GetWindowTextW($h,$tn,256)
          if ($tn.ToString().Trim().ToLower() -eq 'error') { $script:n = $script:n + 1 }
        }
      }
    }
    return $true
  }
  [void][WZ]::EnumWindows($cb,[IntPtr]::Zero)
  return $script:n
}

