  [void][WZ]::SetCursorPos(200, 700); Start-Sleep -Milliseconds 900
  $hiddenY = Get-Top $w.hwnd
  $spanL = $w.x; $spanR = $w.x + $w.w
  Write-Output ("  隐藏态 y=$hiddenY  跨度=[$spanL,$spanR]")
  $ok = 0
  foreach ($i in 1..2) {
    [void][WZ]::SetCursorPos([int](($spanL+$spanR)/2), 2)
    Start-Sleep -Milliseconds 1200
    $rv = Get-Top $w.hwnd
    $revealed = ($rv -gt $hiddenY + 20)
    [void][WZ]::SetCursorPos(200, 700 + $i)
    Start-Sleep -Milliseconds 1600
    $rh = Get-Top $w.hwnd
    $rehidden = ([Math]::Abs($rh - $hiddenY) -le 3)
    $dlg = Get-ErrDialogs
    Write-Output ("  cycle $i : reveal=$revealed (y=$rv)  re-hide=$rehidden (y=$rh)  errorDialog=$dlg")
    if ($revealed -and $rehidden) { $ok++ }
  }
  [void][WZ]::SetCursorPos(40, 2); Start-Sleep -Milliseconds 1400
  $fab = Get-Top $w.hwnd
  Write-Output ("  同边远处 y=$fab  → 不误触发: " + ([Math]::Abs($fab - $hiddenY) -le 3))
  Write-Output ("  循环通过 $ok/2")
}

