$ErrorActionPreference = 'Continue'
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$ud = Join-Path $env:APPDATA "Token Monitor"
$sf = Join-Path $ud 'settings.json'

Write-Output "===== 1. 把窗口尺寸改回可用高度（当前 918 太高，鼠标一碰会盖满屏幕）====="
$s = Get-Content $sf -Raw -Encoding UTF8 | ConvertFrom-Json
Write-Output ("  before: windowBehavior=" + $s.windowBehavior + "  bounds=" + ($s.windowBounds | ConvertTo-Json -Compress))
$s.windowBehavior = 'edge'
$s.windowBounds = [pscustomobject]@{ x = 1080; y = 0; width = 443; height = 377 }
$s.PSObject.Properties.Remove('edgeAutoHideBounds') | Out-Null
$s | ConvertTo-Json -Depth 20 | Set-Content $sf -Encoding UTF8
Write-Output ("  after : windowBehavior=edge  bounds=1080,0 443x377  （停靠右上角）")

Write-Output ""
Write-Output "===== 2. 重启（用 Start-Process，避免 stdout 句柄被继承）====="
Get-Process | Where-Object { $_.ProcessName -like '*Token Monitor*' } | Stop-Process -Force
Start-Sleep -Seconds 3
Start-Process -FilePath "C:\Users\29871\AppData\Local\Programs\Token Monitor\Token Monitor.exe"
Start-Sleep -Seconds 40
$p = @(Get-Process | Where-Object { $_.ProcessName -like '*Token Monitor*' })
Write-Output ("  进程 " + $p.Count + " 个, 合计 {0:N0} MB" -f (($p | Measure-Object WorkingSet64 -Sum).Sum/1MB))

Write-Output ""
Write-Output "===== 3. 窗口与崩溃日志 ====="
Add-Type @"
using System;using System.Text;using System.Runtime.InteropServices;
public class V1 {
 [DllImport("user32.dll")] public static extern bool EnumWindows(P cb, IntPtr l);
 public delegate bool P(IntPtr h, IntPtr l);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)] public static extern int GetWindowTextW(IntPtr h, StringBuilder s, int n);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)] public static extern int GetClassNameW(IntPtr h, StringBuilder s, int n);
 [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
 [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out R r);
 [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
 public struct R { public int l,t,r,b; }
}
"@ -ErrorAction SilentlyContinue
$pids = @($p | ForEach-Object { $_.Id })
$o = New-Object System.Collections.ArrayList
$cb = [V1+P]{
  param($h,$l)
  $r = New-Object V1+R; [void][V1]::GetWindowRect($h,[ref]$r)
  $pid2 = 0; [void][V1]::GetWindowThreadProcessId($h,[ref]$pid2)
  if ($pids -contains [int]$pid2 -and [V1]::IsWindowVisible($h)) {
    $cn = New-Object System.Text.StringBuilder 128; [void][V1]::GetClassNameW($h,$cn,128)
    $w = $r.r-$r.l; $ht = $r.b-$r.t
    if ($w -gt 40 -and $ht -gt 40) {
      $tn = New-Object System.Text.StringBuilder 256; [void][V1]::GetWindowTextW($h,$tn,256)
      [void]$o.Add(("{0}x{1} at ({2},{3}) cls={4} title='{5}'" -f $w,$ht,$r.l,$r.t,$cn.ToString(),$tn.ToString()))
    }
  }
  return $true
}
[void][V1]::EnumWindows($cb,[IntPtr]::Zero)
if ($o.Count -eq 0) { Write-Output "  尚无可见主窗口（启动可能还要更久）" } else { $o | ForEach-Object { Write-Output ("  " + $_) } }
$err = Join-Path $env:TEMP "token-monitor-edge-error.log"
Write-Output ("  edge 错误日志: " + $(if (Test-Path $err) { "存在（本次启动有护栏拒收或异常）" } else { "不存在 ✅" }))
if (Test-Path $err) { Get-Content $err -Encoding UTF8 | Select-Object -Last 3 | ForEach-Object { Write-Output ("    " + $_.Substring(0, [Math]::Min(120, $_.Length))) } }

