input.command:
$ErrorActionPreference = 'Continue'
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
Set-Location "D:\桌面\私人图书馆\7-工具箱\1-project\TokenHub"

Write-Output "===== 1. 当前活动变更 ====="
$listRaw = openspec list --json 2>&1 | Out-String
$list = $listRaw | ConvertFrom-Json
$names = @($list.changes | ForEach-Object { $_.name })
Write-Output ("  活动变更 " + $names.Count + " 个: " + ($names -join ', '))
$list.changes | ForEach-Object { Write-Output ("    " + $_.name + "  schema=" + $_.schema + "  tasks=" + $_.taskStatus) }

Write-Output ""
Write-Output "===== 2. 逐变更检查产物 / 任务 / delta spec ====="
foreach ($n in $names) {
  Write-Output ("  --- " + $n + " ---")
  $st = openspec status --change $n --json 2>&1 | Out-String
  $sj = $st | ConvertFrom-Json
  $notDone = @($sj.artifacts | Where-Object { $_.status -ne 'done' })
  Write-Output ("    产物: " + @($sj.artifacts).Count + " 个, 未完成 " + $notDone.Count + $(if ($notDone.Count) { " -> " + (($notDone | ForEach-Object { $_.id }) -join ',') } else { "" }))
  $tk = Join-Path $sj.changeRoot 'tasks.md'
  if (Test-Path $tk) {
    $t = Get-Content $tk -Encoding UTF8
    Write-Output ("    任务: 完成 " + @($t | Select-String -Pattern '^- \[x\] ').Count + " / 未完成 " + @($t | Select-String -Pattern '^- \[ \] ').Count)
  } else { Write-Output "    任务: 无 tasks.md" }
  $ds = @($sj.artifactPaths.specs.existingOutputPaths)
  Write-Output ("    delta spec " + $ds.Count + " 个:")
  foreach ($d in $ds) {
    $cap = Split-Path (Split-Path $d -Parent) -Leaf
    $main = "openspec\specs\$cap\spec.md"
    Write-Output ("      " + $cap + "  -> 主 spec " + $(if (Test-Path $main) { "已存在（将是 MODIFIED）" } else { "不存在（将是 NEW）" }))
  }
}

Write-Output ""
Write-Output "===== 3. 归档前的 openspec/specs 基线 ====="
if (Test-Path "openspec\specs") { Get-ChildItem "openspec\specs" -Directory | ForEach-Object { Write-Output ("    " + $_.Name) } } else { Write-Output "    （还没有 specs 目录）" }

Write-Output ""
Write-Output "===== 4. 逐个归档（archive 会同时把 delta spec 同步进主 specs）====="
foreach ($n in $names) {
  Write-Output ("  --- archiving " + $n + " ---")
  openspec archive $n --yes 2>&1 | ForEach-Object { Write-Output ("    " + $_) }
}

Write-Output ""
Write-Output "===== 5. 归档后核对 ====="
$l2 = (openspec list --json 2>&1 | Out-String | ConvertFrom-Json)
Write-Output ("  活动变更剩余 " + @($l2.changes).Count + " 个")
Write-Output "  archive 目录:"
Get-ChildItem "openspec\changes\archive" -Directory -ErrorAction SilentlyContinue | Sort-Object Name | ForEach-Object { Write-Output ("    " + $_.Name) }
Write-Output "  主 specs:"
Get-ChildItem "openspec\specs" -Directory -ErrorAction SilentlyContinue | Sort-Object Name | ForEach-Object {
  $sf = Join-Path $_.FullName 'spec.md'
  $rq = if (Test-Path $sf) { @(Select-String -Path $sf -Pattern '^### Requirement: ' -Encoding UTF8).Count } else { 0 }
  Write-Output ("    {0,-38} 需求 {1}" -f $_.Name, $rq)
}
Write-Output ""
Write-Output "===== 6. 全量校验 ====="
openspec validate --all --strict 2>&1 | ForEach-Object { Write-Output ("  " + $_) }
Write-Output ""
Write-Output "===== 7. git ====="
git add -A
git status --short | Select-Object -First 12 | ForEach-Object { Write-Output ("  " + $_) }

